using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;
public sealed class DrpgPhase2Validation:MonoBehaviour {
 readonly List<string> results=new List<string>();const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 DungeonPrototype world;DungeonMapSettings main,second;DungeonSaveData original;string oldPath;
 void Awake(){DontDestroyOnLoad(gameObject);}
 public void Run(){StartCoroutine(Checks());}
 void Check(bool ok,string name){results.Add((ok?"PASS ":"FAIL ")+name);}
 object Get(string name){return typeof(DungeonPrototype).GetField(name,F).GetValue(world);}
 object Call(string name,params object[] args){return typeof(DungeonPrototype).GetMethod(name,F).Invoke(world,args);}
 IEnumerator WaitWorld(DungeonMapSettings map){float deadline=Time.realtimeSinceStartup+20;while(Time.realtimeSinceStartup<deadline){var next=UnityEngine.Object.FindFirstObjectByType<DungeonPrototype>();if(SceneManager.GetActiveScene().path!=DigitalKingdomSettings.Current.scenePath&&next!=null&&next.mapSettings==map&&next.gameObject.scene==SceneManager.GetActiveScene()&&typeof(DungeonPrototype).GetField("view",F).GetValue(next)!=null){world=next;world.enabled=false;yield return null;yield break;}yield return null;}throw new Exception("Timeout piso "+map.name);}
 void Travel(DungeonMapSettings map,Vector2Int cell){Call("TravelMapDoor",new DungeonMapEntity{kind=DungeonEntityKind.Door,doorKind=DungeonDoorKind.Transition,destinationMap=map,destinationCell=cell});}
 void FinishDialogue(){var dialog=(WorldDialogue)Get("worldDialogue");int n=0;while(dialog.Active&&n++<50){dialog.CompleteLetters();dialog.Advance(50);}}
 bool DiagnosticPass(DungeonMapSettings map){var type=Type.GetType("DungeonMapDiagnostics, Assembly-CSharp-Editor");var report=type.GetMethod("Analyze").Invoke(null,new object[]{map});return ((List<string>)report.GetType().GetField("errors").GetValue(report)).Count==0;}
 IEnumerator Checks(){
  world=UnityEngine.Object.FindFirstObjectByType<DungeonPrototype>();main=DungeonMapSettings.Current;second=Resources.Load<DungeonMapSettings>("DrpgPhase2Tests/FloorB");original=world.CaptureDungeonSave();oldPath=DungeonSaveStore.editorTestPath;DungeonSaveStore.editorTestPath=Path.GetFullPath("Tests/Phase2Save.json");
  try{
   world.enabled=false;var a=world.CaptureDungeonSave();a.introductionCompleted=true;
   var boss=a.enemies.Find(e=>e.placementId==DigitalKingdomSettings.Current.requiredBossId);if(boss==null)throw new Exception("Fixture Makong ausente");boss.defeated=true;boss.currentHP=0;
   var chest=main.entities.objects.Find(e=>e.kind==DungeonEntityKind.Chest&&e.chestKind==DungeonChestKind.Normal);var state=a.entityStates.Find(e=>e.id==chest.id);if(state==null){state=new DungeonEntityState{id=chest.id};a.entityStates.Add(state);}state.opened=true;
   world.RestoreDungeonSave(a);typeof(DungeonPrototype).GetField("startMenuOpen",F).SetValue(world,false);
   var visitedBefore=world.CaptureDungeonSave().visited.Count;bool reveal=(bool)Call("TryRevealNodeMap","node.refuge",null);if(reveal)Call("FinishMapReveal");a=world.CaptureDungeonSave();Check(reveal&&a.visited.Count==visitedBefore&&a.explored.Count>a.visited.Count,"Teleport reveals explored without visits");
   var sourceCell=a.cell;Travel(second,new Vector2Int(1,1));yield return WaitWorld(second);var b=world.CaptureDungeonSave();Check(b.activeMapId==second.mapId&&b.maps.Exists(s=>s.mapId==main.mapId),"First transition stores source snapshot");Check(b.visited.Count==1&&!b.entityStates.Exists(e=>e.id==chest.id),"New floor has independent visits and chests");Check(b.enemies.Count==1,"First visit creates configured enemy once");
   var doors=(Dictionary<string,DungeonDoor>)Get("mapDoors");doors["test-phase2-door"].SetOpenImmediately();Call("EntityState","test-phase2-chest");b=world.CaptureDungeonSave();b.entityStates.Find(e=>e.id=="test-phase2-chest").opened=true;b.enemies[0].currentHP=2;b.triggeredEncounters=new[]{"test-phase2-enemy","test-phase2-event"};world.RestoreDungeonSave(b);Call("WarpPlayer",new Vector2Int(1,2),1);b=world.CaptureDungeonSave();Check(b.visited.Contains(new Vector2Int(1,2)),"Physical arrival adds a visit");var enemyId=b.enemies[0].instanceId;
   Travel(main,sourceCell);yield return WaitWorld(main);a=world.CaptureDungeonSave();Check(a.entityStates.Find(e=>e.id==chest.id).opened,"Chest A remains opened after return");Check(a.enemies.Exists(e=>e.placementId==boss.placementId&&e.defeated),"Defeated boss A remains defeated");Check(a.explored.Count>0&&a.visited.Count>0,"Floor A discovery and visits restored");
   Travel(second,new Vector2Int(1,1));yield return WaitWorld(second);b=world.CaptureDungeonSave();Check(b.enemies.Count==1&&b.enemies[0].instanceId==enemyId&&b.enemies[0].currentHP==2,"Enemy identity and HP restored without duplication");Check(b.entityStates.Find(e=>e.id=="test-phase2-chest").opened&&((Dictionary<string,DungeonDoor>)Get("mapDoors"))["test-phase2-door"].IsOpen,"Floor B chest and door remain opened");Check(Array.IndexOf(b.triggeredEncounters,"test-phase2-event")>=0&&b.visited.Contains(new Vector2Int(1,2)),"Floor B event and visits preserved");
   b.enemies[0].defeated=true;b.enemies[0].currentHP=0;world.RestoreDungeonSave(b);b=world.CaptureDungeonSave();for(int slot=0;slot<DungeonSaveStore.SlotCount;slot++){DungeonSaveStore.Write(b,slot,"Fase 2 fixture "+slot);var loaded=DungeonSaveStore.Read(slot);Check(loaded.version==2&&loaded.activeMapId==second.mapId&&loaded.maps.Count==2,"Version 2 roundtrip slot "+(slot+1));}
   Travel(main,sourceCell);yield return WaitWorld(main);world.RestoreDungeonSave(DungeonSaveStore.Read(0));yield return WaitWorld(second);b=world.CaptureDungeonSave();Check(b.enemies.Count==1&&b.enemies[0].defeated&&b.enemies[0].instanceId==enemyId,"Loading from other floor restores dead enemy and correct map");
   var legacy=DungeonMapPersistence.Copy(original);legacy.version=1;legacy.activeMapId=null;legacy.maps=null;legacy.visited=null;legacy.explored=new List<Vector2Int>{sourceCell,new Vector2Int(2,1),new Vector2Int(3,1)};DungeonMapPersistence.Normalize(legacy,main);Check(legacy.visited.Count==1&&legacy.visited[0]==legacy.cell&&legacy.explored.Count==3,"Legacy migration does not invent visits from explored");
   Travel(main,sourceCell);yield return WaitWorld(main);a=world.CaptureDungeonSave();a.city=a.city??new DigitalKingdomProgress();a.city.firstVisitCompleted=true;a.city.inCity=false;world.RestoreDungeonSave(a);Check(world.EnterDigitalKingdom(),"City transition accepts defeated boss");yield return null;float end=Time.realtimeSinceStartup+20;DigitalKingdomController city=null;while(city==null&&Time.realtimeSinceStartup<end){city=UnityEngine.Object.FindFirstObjectByType<DigitalKingdomController>();yield return null;}if(city==null)throw new Exception("City scene absent");city.enabled=false;world=city.stateHost;FinishDialogue();var citySave=world.CaptureDungeonSave();Check(citySave.city.returnMapId==main.mapId&&citySave.maps.Exists(s=>s.mapId==second.mapId&&s.enemies.Exists(e=>e.defeated)),"City bridge preserves floor snapshots and stable return ID");DungeonSaveStore.Write(citySave,0,"City with two floors");world.RestoreDungeonSave(DungeonSaveStore.Read(0));FinishDialogue();Check(world.CaptureDungeonSave().maps.Count==2,"City save/load retains both floors");world.ExitDigitalKingdom();yield return WaitWorld(main);a=world.CaptureDungeonSave();Check(a.maps.Exists(s=>s.mapId==second.mapId)&&a.activeMapId==main.mapId,"City exit restores source floor and other snapshot");Travel(second,new Vector2Int(1,1));yield return WaitWorld(second);b=world.CaptureDungeonSave();Check(b.enemies[0].defeated&&b.entityStates.Find(e=>e.id=="test-phase2-chest").opened,"City roundtrip preserves other floor permanent states");
   Check(DiagnosticPass(main)&&DiagnosticPass(second),"Phase 1 validators still pass both maps");var movement=DungeonMovementSettings.Current;Check(!movement.experimental&&movement.stepSeconds==.18f&&movement.turnSeconds==.18f&&!movement.continuousMovement&&!movement.repeatTurns&&movement.inputBufferSeconds==0,"Original movement unchanged");results.Add("PASS Completed all phase 2 checks");
  }finally{DungeonSaveStore.editorTestPath=oldPath;File.WriteAllLines("Tests/DrpgPhase2Results.txt",results);Debug.Log("Phase 2 checks\n"+string.Join("\n",results.ToArray()));if(world!=null){world.RestoreDungeonSave(original);world.enabled=true;}}
 }
}
